import{c as a,Q as r,j as o,m as s}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"HarnessX: A Composable, Adaptive, and Evolvable Agent Harness Foundry","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.14249","title":"HarnessX: A Composable, Adaptive, and Evolvable Agent Harness Foundry","archived_date":"2026-06-18T00:00:00.000Z","arxiv_id":2606.14249,"authors":["Tingyang Chen","Shuo Lu","Kang Zhao","Weicheng Meng","Hanlin Teng","Tianhao Li","Chao Li","Xule Liu","Jian Liang","Zhizhong Zhang","Yuan Xie","Heng Qu","Kun Shao","Jian Luan"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2606.14249v1","pdf_path":"pdfs/2606.14249.pdf","published_date":"2026-06-12T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-12-harnessx-composable-adaptive-evolvable-harness-foundry-2606-14249.md","filePath":"research/papers/2026-06-12-harnessx-composable-adaptive-evolvable-harness-foundry-2606-14249.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-06-12-harnessx-composable-adaptive-evolvable-harness-foundry-2606-14249.md"};function n(i,e,l,d,c,h){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="harnessx-a-composable-adaptive-and-evolvable-agent-harness-foundry" tabindex="-1">HarnessX: A Composable, Adaptive, and Evolvable Agent Harness Foundry <a class="header-anchor" href="#harnessx-a-composable-adaptive-and-evolvable-agent-harness-foundry" aria-label="Permalink to &quot;HarnessX: A Composable, Adaptive, and Evolvable Agent Harness Foundry&quot;">​</a></h1><p><strong>Authors</strong>: Tingyang Chen, Shuo Lu, Kang Zhao, Weicheng Meng, Hanlin Teng, Tianhao Li, Chao Li, Xule Liu, Jian Liang, Zhizhong Zhang, Yuan Xie, Heng Qu, Kun Shao, Jian Luan <strong>Published</strong>: June 12, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.14249" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.14249</a> · <a href="https://arxiv.org/html/2606.14249v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.14249 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.14249" target="_blank" rel="noreferrer">research/papers/pdfs/2606.14249.pdf</a> (43 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>AI agent performance depends critically on the runtime harness, comprising the prompts, tools, memory, and control flow that mediate how a model observes, reasons, and acts. Yet today&#39;s harnesses remain largely hand-crafted and static: each new model or task still demands bespoke scaffolding, and the rich traces produced during execution are rarely distilled back into systematic improvement. We introduce HarnessX, a foundry for composable, adaptive, and evolvable agent harnesses. HarnessX assembles typed harness primitives via a substitution algebra, adapts them through AEGIS, a trace-driven multi-agent evolution engine grounded in an operational mirror between symbolic adaptation and reinforcement learning, and closes the harness–model loop by turning trajectories into both harness updates and model training signal. Across five benchmarks (ALFWorld, GAIA, WebShop, τ³-Bench, and SWE-bench Verified), HarnessX yields an average gain of +14.5% (up to +44.0%), with gains largest where baselines are lowest. [...] The complete codebase will be open-sourced in a future release.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><p>HarnessX 把 agent harness 從「靜態手工 scaffolding」提升為 <strong>first-class、可組合、可從 traces 自動演化的物件</strong>。三大支柱：</p><ol><li><strong>Composition（§3 Harness as First-Class Object）</strong> — Typed processor 抽象 + substitution algebra。每個 processor 掛在 lifecycle hook（task/step start、before/after model call、tool op），以型別合約消費/產出事件。組合由三 metadata 控制：<code>_singleton_group</code>（互斥）、<code>_order</code>（PRE/NORMAL/POST）、<code>_after</code>（軟依賴）。</li><li><strong>Adaptation（§4 AEGIS）</strong> — Trace-driven 多 agent 演化引擎，建立在「symbolic adaptation ↔ RL」的 operational mirror 上。四階段 loop： <ul><li><strong>Digester</strong>：每迭代 ~10M tokens raw traces → 結構化摘要（binary outcome、failure 分類、關聯元件、support 引用）</li><li><strong>Planner</strong>：建 adaptation landscape，識別失敗任務 / 未探索 edit 方向 / 適用元件類型，防 under-exploration</li><li><strong>Evolver</strong>：產生 typed builder 候選操作，每個附「change manifest」（預期效果 + 預期 regression 點）</li><li><strong>Critic + 確定性 Gate</strong>：Critic 對抗 reward hacking；Gate 強制 <strong>seesaw constraint</strong>（候選不得 regress 任何先前通過任務）。LLM 探索與提案，typed structure + 確定性 gate 決定上線</li></ul></li><li><strong>Co-Evolution（§5）</strong> — Cross-Harness GRPO，把 reward-annotated trajectories 餵回 model finetuning，閉合 harness–model loop（off-policy / mixed-policy buffer）。</li></ol><h3 id="九維行為分類-§3-3" tabindex="-1">九維行為分類（§3.3） <a class="header-anchor" href="#九維行為分類-§3-3" aria-label="Permalink to &quot;九維行為分類（§3.3）&quot;">​</a></h3><p>D1 模型選擇 · D2 上下文組裝 · D3 記憶管理 · D4 工具生態 · D5 執行環境 · D6 評估與獎勵 · D7 控制與安全 · D8 可觀測性 · D9 訓練橋接。AEGIS 跨全九維演化；<strong>D2 / D4 為最高頻修改目標</strong>。</p><h3 id="關鍵實驗結果-§6" tabindex="-1">關鍵實驗結果（§6） <a class="header-anchor" href="#關鍵實驗結果-§6" aria-label="Permalink to &quot;關鍵實驗結果（§6）&quot;">​</a></h3><ul><li><strong>平均絕對增益 +14.5%</strong>（5 benchmark × 3 task-agent family，最多 15 輪演化），範圍 0.0%~+44.0%（15 組中 14 組提升）。</li><li><strong>逆縮放規律</strong>：baseline 最低處增益最大（Qwen on ALFWorld +44.0% vs Sonnet +11.2%）。</li><li><strong>協同演化加成</strong>：harness 演化 + model RL = 額外 +4.7%。</li><li><strong>Variant Isolation（§4.5）</strong>：異質任務集（GAIA）單一 harness 演化會因需求衝突停滯；維護最多 K 個 variant 按任務路由，恢復穩定增益（+13.6%，15 輪非退化）。</li></ul><h3 id="限制-開放性-§7" tabindex="-1">限制 / 開放性（§7） <a class="header-anchor" href="#限制-開放性-§7" aria-label="Permalink to &quot;限制 / 開放性（§7）&quot;">​</a></h3><ul><li>依賴 trace richness：稀疏 trace 削弱 Digester 訊號。</li><li>Operational mirror 的 scope 有界（§7.3）；cost-performance tradeoff 顯著（多 agent 演化成本高）。</li><li>Codebase 標注「未來釋出」——目前無法直接落地。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>The Loop ↔ AEGIS 對齊</strong>：<code>OBSERVE→IDENTIFY→PROPOSE→APPLY→TEST→RECORD</code> 與 <code>Digester→Planner→Evolver→Critic+Gate</code> 語義同構；可作 The Loop 計算化藍圖的參考，但 AEGIS 假設「自動化 trace pipeline + 確定性 benchmark gate」，本 workspace 目前無此基建。</li><li><strong><code>unverified_success</code> 閘門理論背書</strong>：seesaw constraint = core.md「能通過任何實作的測試 = 沒有測試」的數學形式化。</li><li><strong>Trace store 演化方向</strong>：Digester 壓縮模式可作 <code>memory-compactor</code> 的長期參考。</li><li>⚠️ 落地門檻：需 traces 自動化 + 確定性 eval harness，皆為 workspace 尚未具備之前置；列為長期（P2）方向。</li></ul>',19)])])}const u=a(t,[["render",n]]);export{p as __pageData,u as default};
